function integratedSkillsHtml(level, isMain) {
  const P = B.armsIntegrated, alloc = isMain && S.hero ? armsHeroData(S.hero, level) : P.line(level);
  const auto = B.autoOf('warrior','arms');
  const items = P.slots(level,alloc,isMain).map(function (slot) {
    const label = slot.source === 'talent' ? 'Талант мейна' : (slot.available ? 'с '+slot.unlockLevel+' ур.' : 'Откроется на '+slot.unlockLevel+' уровне');
    const cost = slot.id === 'execute' ? B.rageCostText(slot.id) : slot.rage;
    return '<li data-integrated-skill="'+slot.id+'" data-available="'+slot.available+'" data-own-level="'+level+'"'+(slot.available?'':' style="opacity:.55"')+'>'+wowIcon(B.SKILLS[slot.id])+' <b>'+esc(slot.name)+'</b> · '+esc(label)+' · ярость '+esc(cost)+' · перезарядка '+slot.cd+'<br>'+esc(slot.description)+'</li>';
  }).join('');
  const passives = P.passives(level,alloc).map(p=>'<li data-integrated-passive="'+p.id+'">'+wowIcon(p)+' <b>'+esc(p.name)+'</b><br>'+esc(p.text)+'</li>').join('');
  const aura = isMain && level >= 15 ? B.auraOf('warrior','arms') : null;
  return '<details class="sk" open data-integrated-level="'+level+'"><summary>'+(level<15?'Учебный набор воина':'Умения Оружия')+'</summary><p>Автоатака: '+esc(auto.name)+'. '+(level<15?'Аура и пассивки специализации закрыты до 15 уровня.':'Временная схема до 30 уровня; не окончательный баланс до 60.')+'</p><ul>'+items+passives+'</ul>'+(aura?'<p>Аура: '+esc(aura.name)+' · '+esc(aura.text)+'</p>':'')+'</details>';
}
function integratedUnitPassives(u) { return u.integratedArms ? B.armsIntegrated.passives(u.level,u.tal) : passivesOf(B.specOf(u.cls,u.spec)); }
function integratedRageText(u,id) { const cost=u.integratedArms?B.armsIntegrated.cost(id,u.tal):undefined;return id==='execute'||cost===undefined?B.rageCostText(id):String(cost); }

